package kw.urtv.home;
import org.json.*;import kw.urtv.shared.ContentPolicy;import java.time.*;import java.time.format.DateTimeFormatter;import java.util.*;
/** Normalize only display fields; scores absent from a feed are never invented. */
final class FootballResults {
 static boolean allowed(JSONObject e){return e!=null&&ContentPolicy.team(e.optString("homeId"),e.toString())&&ContentPolicy.team(e.optString("awayId"),e.toString());}
 static JSONArray merge(JSONObject recent,JSONObject upcoming,Instant now){Map<String,JSONObject> found=new HashMap<>();for(JSONObject root:new JSONObject[]{recent,upcoming}){JSONArray events=root.optJSONArray("events");if(events==null)continue;for(int i=0;i<events.length();i++)try{JSONObject e=events.getJSONObject(i);JSONArray comps=e.getJSONArray("competitions");JSONObject c=comps.getJSONObject(0);JSONArray teams=c.getJSONArray("competitors");if(teams.length()!=2)continue;JSONObject h=null,a=null;for(int j=0;j<2;j++){JSONObject side=teams.getJSONObject(j);if("home".equals(side.optString("homeAway")))h=side;else if("away".equals(side.optString("homeAway")))a=side;}if(h==null||a==null)continue;JSONObject ht=h.getJSONObject("team"),at=a.getJSONObject("team");if(!ContentPolicy.team(ht.optString("id"),ht.toString())||!ContentPolicy.team(at.optString("id"),at.toString())||!ContentPolicy.text(e.optString("name")))continue;Instant date=OffsetDateTime.parse(e.getString("date")).toInstant();if(date.isBefore(now.minusSeconds(14*86400))||date.isAfter(now.plusSeconds(45*86400)))continue;JSONObject status=c.getJSONObject("status").getJSONObject("type");String state=status.optString("state");JSONObject row=new JSONObject().put("id",e.getString("id")).put("date",date.toString()).put("homeId",ht.getString("id")).put("awayId",at.getString("id")).put("home",ht.getString("displayName")).put("away",at.getString("displayName")).put("timeValid",c.optBoolean("timeValid",true)).put("state",state).put("status",status.optString("name")).put("homeScore",score(h)).put("awayScore",score(a));if(allowed(row))found.put(row.getString("id"),row);}catch(Exception ignored){}}
 ArrayList<JSONObject> past=new ArrayList<>(),future=new ArrayList<>();for(JSONObject e:found.values())if("post".equals(e.optString("state")))past.add(e);else future.add(e);past.sort((a,b)->b.optString("date").compareTo(a.optString("date")));future.sort(Comparator.comparing(a->a.optString("date")));JSONArray out=new JSONArray();for(int i=0;i<Math.min(3,past.size());i++)out.put(past.get(i));for(int i=0;i<Math.min(3,future.size());i++)out.put(future.get(i));return out;}
 private static String score(JSONObject side){Object raw=side.opt("score");String s=raw instanceof JSONObject?((JSONObject)raw).optString("displayValue",""):raw instanceof String?(String)raw:"";return s.matches("[0-9]{1,3}")?s:"—";}
 static String label(JSONObject e,ZoneId zone){try{String state=e.optString("state"),status=e.optString("status");String tag="post".equals(state)?"انتهت":"in".equals(state)?"جارية · نتيجة آخر تحديث":"قادمة";if(status.contains("POSTPONED"))tag="مؤجلة";if(status.contains("CANCEL"))tag="ملغاة";String score="pre".equals(state)?" × ":"  "+e.optString("homeScore","—")+" — "+e.optString("awayScore","—")+"  ";return e.optString("home")+score+e.optString("away")+"\n"+tag+" · "+DateTimeFormatter.ofPattern(e.optBoolean("timeValid",true)?"EEE d MMM · HH:mm":"EEE d MMM",new Locale("ar")).withZone(zone).format(OffsetDateTime.parse(e.getString("date")).toInstant())+(e.optBoolean("timeValid",true)?"":" · الوقت لم يُحدد");}catch(Exception ex){return "موعد غير متاح";}}
}
